SourceCode.Declaration:
/// <summary>
/// [PackageUrl] is the blob SAS URL the app already uploaded the counted-quantity package to via
/// the public `GetAzureWriteUrl` OData action - see CountingJournalRepository.submitCounts.
/// The rest is the audit carried by every submission (ISO 8601 UTC strings for timestamps);
/// SubmissionId is the client-generated idempotency key. Storing the audit is a TODO for the
/// X++ owner.
/// </summary>
[DataContractAttribute]
class HSMobileOpsImportCountsRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             packageUrl;
    str             claimToken;
    str             submissionId;
    str             userId;
    str             deviceId;
    str             startedAtUtc;
    str             submittedAtUtc;
    int             passNumber;
    str             originType;

}

